import json, subprocess, time, sys, random
sys.path.insert(0,'/app/tmp/work')
from stress import mk_trace
rng = random.Random(5)
K = 8
fields = [{"name":"n%d"%i,"type":"SIZE","min":0,"max":1000} for i in range(6)]

def full_tree(depth, ty, dollar):
    if depth == 4:
        return {"field": rng.choice(fields)["name"], "at": "$" if dollar else rng.randrange(K)}
    if rng.random()<0.5:
        return {"add":[full_tree(depth+1,ty,dollar), full_tree(depth+1,ty,dollar)]}
    return {"scale": rng.randint(-8,8), "term": full_tree(depth+1,ty,dollar)}

def count(t):
    ks=set(t)
    if ks in ({"field","at"},{"const","type"},{"aggregate","field","from","to"}): return 1
    if ks=={"scale","term"}: return 1+count(t["term"])
    return 1+count(t["add"][0])+count(t["add"][1])

def make(dollar, agg):
    atoms=[]
    for i in range(20):
        if agg:
            # aggregate-heavy: many means (hoisted once per context)
            def m():
                f=rng.choice(fields)["name"]; a=rng.randrange(K); z=rng.randint(a,K-1)
                return {"aggregate":"mean","field":f,"from":a,"to":z}
            left = {"add":[{"add":[m(),m()]},{"add":[m(),m()]}]}
            right = {"add":[{"add":[m(),m()]},{"add":[m(),m()]}]}
            atoms.append({"quantifier":"any","from":0,"to":K-1,
                          "predicate":{"cmp":"le","left":left,"right":right}})
        else:
            atoms.append({"quantifier":"any" if i%2 else "all","from":0,"to":K-1,
                          "predicate":{"cmp":"le","left":full_tree(1,"SIZE",dollar),
                                       "right":full_tree(1,"SIZE",dollar)}})
    return atoms

def rand_row(): return [rng.randint(0,1000) for _ in fields]
train=[mk_trace("tr%d"%i,"s%d"%(i%16),[rand_row() for _ in range(258)]) for i in range(16)]
probes=[mk_trace("pr0","s0",[rand_row() for _ in range(128)])]
queries=[mk_trace("q0","s0",[rand_row() for _ in range(1031)])]

for label, dollar, agg in [("all-dollar depth4", True, False), ("fixed depth4", False, False), ("aggregate mean heavy", False, True)]:
    atoms = make(dollar, agg)
    req={"version":1,"window":K,"schema":fields,"atoms":atoms,
         "policy":{"max_width":4,"min_support":1,"min_witness":1},
         "train":train,"probes":probes,"queries":queries}
    text=json.dumps(req)
    t0=time.time()
    p=subprocess.run(['/app/submission/run.sh'],input=text.encode(),capture_output=True,cwd='/app/submission')
    el=time.time()-t0
    r=json.loads(p.stdout.decode())
    print('%-22s nodes/atom=%s in=%d rc=%d wall=%.2f classes=%d members=%d' % (
        label, [count(a['predicate']['left'])+count(a['predicate']['right']) for a in atoms][:3],
        len(text), p.returncode, el, len(r['classes']), sum(c['members'] for c in r['classes'])))
    if p.stderr: print('  stderr', p.stderr.decode()[:200])
EOF
